<script setup lang="ts">
import{onMounted,ref}from"vue";import{api}from"@/api";import{useUserStore}from"@/stores/user";import{err,fmt}from"@/utils/format";import type{AnalysisHistory,GrowthHistory,ResumeHistory}from"@/types/api";import PageHeader from"@/components/common/PageHeader.vue";import StateView from"@/components/common/StateView.vue";
type Row={id:number;type:string;target:string;summary:string;score?:number;created?:string};const user=useUserStore(),rows=ref<Row[]>([]),loading=ref(true),error=ref(''),detail=ref<any>(null),dialog=ref(false);async function load(){loading.value=true;try{const[a,r,g]=await Promise.all([api.analyses(user.userId!),api.resumes(user.userId!),api.growths(user.userId!)]);rows.value=[...a.map((x:AnalysisHistory)=>({id:x.id,type:'就业画像',target:x.target_job||'综合评估',summary:x.technical_direction,score:x.comprehensive_score,created:x.created_at})),...r.map((x:ResumeHistory)=>({id:x.id,type:'简历优化',target:x.target_job,summary:'简历表达与岗位适配优化',score:x.resume_score,created:x.created_at})),...g.map((x:GrowthHistory)=>({id:x.id,type:'成长规划',target:x.target_job,summary:x.expected_timeline,created:x.created_at}))].sort((x,y)=>String(y.created).localeCompare(String(x.created)))}catch(e){error.value=err(e)}finally{loading.value=false}}async function open(row:Row){detail.value=row.type==='就业画像'?await api.analysisDetail(row.id):row.type==='简历优化'?await api.resumeDetail(row.id):await api.growthDetail(row.id);dialog.value=true}onMounted(load);
</script><template><div><PageHeader title="分析记录" description="集中查看已持久化的就业画像、简历优化与成长规划结果。"/><el-alert title="岗位匹配后端目前仅支持按记录编号查询，尚无按学生列出历史的接口，因此本页不虚构岗位匹配记录。" type="info" :closable="false" show-icon/><StateView :loading="loading" :error="error" :empty="!rows.length" empty-text="暂无分析记录" @retry="load"><template #content><div class="table-wrap"><el-table :data="rows" stripe><el-table-column prop="type" label="类型" width="120"><template #default="s"><el-tag effect="plain">{{s.row.type}}</el-tag></template></el-table-column><el-table-column prop="target" label="目标岗位" min-width="180"/><el-table-column prop="summary" label="摘要" min-width="260" show-overflow-tooltip/><el-table-column label="评分" width="100"><template #default="s">{{s.row.score??'--'}}</template></el-table-column><el-table-column label="时间" width="190"><template #default="s">{{fmt(s.row.created)}}</template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="s"><el-button link type="primary" @click="open(s.row)">查看详情</el-button></template></el-table-column></el-table></div></template></StateView><el-dialog v-model="dialog" title="历史记录详情" width="min(760px, 94vw)"><pre class="json-detail">{{JSON.stringify(detail?.result||detail,null,2)}}</pre></el-dialog></div></template>
